section.mermaid:
flowchart TD
  D[ticket-set.draft] --> C0{schema}
  C0 -- fail --> R400[validator.refused 400 schema]
  C0 --> C1{anchor at repo_sha is current on main}
  C1 -- moved --> R1[validator.refused 422 anchor_moved]
  C1 --> C2{files and new_paths}
  C2 -- fail --> R2[validator.refused 422 files]
  C2 --> C3{records: kinds exist}
  C3 -- fail --> R3[validator.refused 422 records]
  C3 --> C4{depends_on acyclic}
  C4 -- fail --> R4[validator.refused 422 depends]
  C4 --> C5{size}
  C5 -- fail --> R5[validator.refused 422 size]
  C5 --> C6{duplicate}
  C6 -- fail --> R6[validator.refused 422 duplicate]
  C6 --> C7[run and classify every acceptance command]
  C7 -- not admitted --> R7[validator.refused 422 acceptance]
  C7 --> M[Store.Do accept: mint, tickets, set row, ticket-set.accepted 201]
